import{_ as t,o as i,c as d,b as v}from"./index-C1GwWGto.js";const l={},s={class:"help-page"};function o(c,a){return i(),d("div",s,[...a[0]||(a[0]=[v('<div class="container" data-v-8149a3aa><h2 data-v-8149a3aa>🔒 隐私政策</h2><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>更新日期：2024年1月1日</h3><p data-v-8149a3aa>欢迎使用PetLife！我们重视您的隐私保护，本隐私政策旨在说明我们如何收集、使用、存储和保护您的个人信息。</p></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>一、我们收集的信息</h3><ul data-v-8149a3aa><li data-v-8149a3aa><strong data-v-8149a3aa>注册信息：</strong>当您注册账户时，我们会收集您的手机号、密码等信息。</li><li data-v-8149a3aa><strong data-v-8149a3aa>宠物信息：</strong>您添加的宠物档案信息，包括宠物名称、品种、年龄、疫苗记录等。</li><li data-v-8149a3aa><strong data-v-8149a3aa>服务信息：</strong>您预约的门店服务记录、订单信息等。</li><li data-v-8149a3aa><strong data-v-8149a3aa>购物信息：</strong>您在商城购买商品的订单信息、收货地址等。</li><li data-v-8149a3aa><strong data-v-8149a3aa>社区信息：</strong>您发布的帖子、评论等内容。</li><li data-v-8149a3aa><strong data-v-8149a3aa>设备信息：</strong>您使用的设备类型、操作系统、IP地址等。</li></ul></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>二、我们如何使用您的信息</h3><ul data-v-8149a3aa><li data-v-8149a3aa>为您提供宠物档案管理、门店服务预约、商城购物等核心功能。</li><li data-v-8149a3aa>向您发送订单通知、服务提醒等重要信息。</li><li data-v-8149a3aa>优化我们的服务，改善用户体验。</li><li data-v-8149a3aa>保障平台安全，防止欺诈行为。</li><li data-v-8149a3aa>根据法律法规要求进行信息披露。</li></ul></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>三、我们如何保护您的信息</h3><ul data-v-8149a3aa><li data-v-8149a3aa>采用加密技术保护您的个人信息传输和存储。</li><li data-v-8149a3aa>严格限制访问您个人信息的人员范围。</li><li data-v-8149a3aa>定期进行安全审计，确保系统安全。</li><li data-v-8149a3aa>如发生数据泄露，我们会及时通知您并采取补救措施。</li></ul></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>四、您的权利</h3><ul data-v-8149a3aa><li data-v-8149a3aa>您可以访问、修改和删除您的个人信息。</li><li data-v-8149a3aa>您可以随时注销您的账户。</li><li data-v-8149a3aa>您可以拒绝我们收集非必要的信息。</li></ul></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>五、第三方服务</h3><p data-v-8149a3aa>我们的平台可能包含第三方服务链接，这些第三方服务有其独立的隐私政策。我们不对第三方服务的隐私行为负责。</p></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>六、政策变更</h3><p data-v-8149a3aa>我们可能会不定期更新本隐私政策。更新后，我们会通过平台通知您。</p></div><div class="policy-section" data-v-8149a3aa><h3 data-v-8149a3aa>七、联系我们</h3><p data-v-8149a3aa>如果您对本隐私政策有任何疑问，请通过&quot;联系客服&quot;页面与我们联系。</p></div></div>',1)])])}const e=t(l,[["render",o],["__scopeId","data-v-8149a3aa"]]);export{e as default};
